package io.fulfillx.notification.persistence;
import io.fulfillx.notification.domain.NotificationMessage;import io.fulfillx.notification.messaging.OrderEventEnvelope;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;import java.sql.ResultSet;import java.util.UUID;
@Repository public class NotificationStore{
 private final JdbcTemplate jdbc;public NotificationStore(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public record Work(NotificationMessage message,UUID attemptId,UUID deliveryToken,int attemptNumber){}
 private record Row(NotificationMessage message,String status,java.time.Instant leaseUntil){}
 @Transactional public Work prepare(OrderEventEnvelope e){UUID order=validate(e);jdbc.update("INSERT INTO processed_messages(message_id,message_type) VALUES (?,?) ON CONFLICT(message_id) DO NOTHING",e.messageId(),e.messageType());String subject=subject(e),body=body(e,order);String recipient="order-"+order+"@example.invalid";
  jdbc.update("INSERT INTO notifications(notification_id,source_message_id,order_id,event_type,correlation_id,recipient,subject,body,status) VALUES (?,?,?,?,?,?,?,?, 'PENDING') ON CONFLICT(order_id,event_type) DO NOTHING",UUID.randomUUID(),e.messageId(),order,e.messageType(),e.correlationId(),recipient,subject,body);
  var row=jdbc.query("SELECT notification_id,source_message_id,order_id,correlation_id,event_type,recipient,subject,body,status,lease_until FROM notifications WHERE order_id=? AND event_type=? FOR UPDATE",rs->rs.next()?map(rs):null,order,e.messageType());if(row==null)throw new IllegalStateException("Notification record unavailable");var notification=row.message();if("DELIVERED".equals(row.status()))return null;if("SENDING".equals(row.status())&&row.leaseUntil()!=null&&row.leaseUntil().isAfter(java.time.Instant.now()))throw new IllegalStateException("A notification delivery attempt is already in progress.");
  jdbc.update("UPDATE delivery_attempts SET status='FAILED',error_code='PROCESS_REDELIVERED',completed_at=CURRENT_TIMESTAMP WHERE notification_id=? AND status='STARTED'",notification.notificationId());Integer n=jdbc.queryForObject("SELECT COALESCE(MAX(attempt_number),0)+1 FROM delivery_attempts WHERE notification_id=?",Integer.class,notification.notificationId());UUID attempt=UUID.randomUUID();jdbc.update("INSERT INTO delivery_attempts(attempt_id,notification_id,attempt_number,status) VALUES (?,?,?,'STARTED')",attempt,notification.notificationId(),n);
  UUID token=UUID.randomUUID();jdbc.update("UPDATE notifications SET status='SENDING',delivery_token=?,lease_until=CURRENT_TIMESTAMP+INTERVAL '120 seconds' WHERE notification_id=?",token,notification.notificationId());return new Work(notification,attempt,token,n);
 }
 @Transactional public void complete(Work work,boolean sent,int maxAttempts){jdbc.update("UPDATE delivery_attempts SET status=?,error_code=?,completed_at=CURRENT_TIMESTAMP WHERE attempt_id=?",sent?"DELIVERED":"FAILED",sent?null:"DELIVERY_FAILED",work.attemptId());int updated=jdbc.update("UPDATE notifications SET status=?,delivered_at=CASE WHEN ? THEN CURRENT_TIMESTAMP ELSE delivered_at END,delivery_token=NULL,lease_until=NULL WHERE notification_id=? AND delivery_token=?",sent?"DELIVERED":work.attemptNumber()>=maxAttempts?"FAILED":"PENDING",sent,work.message().notificationId(),work.deliveryToken());if(updated!=1)throw new IllegalStateException("Notification delivery lease was lost before completion.");}
 private UUID validate(OrderEventEnvelope e){if(e==null||e.messageId()==null||e.messageType()==null||e.schemaVersion()!=1||e.occurredAt()==null||e.correlationId()==null||e.causationId()==null||!"Order".equals(e.aggregateType())||e.aggregateId()==null||e.payload()==null)throw new IllegalArgumentException("Invalid Order event envelope");if(!java.util.Set.of("OrderConfirmed","OrderRejected","OrderCancelled").contains(e.messageType()))throw new IllegalArgumentException("Unsupported Order event type");UUID order;try{order=UUID.fromString(e.payload().path("orderId").asText());}catch(Exception ex){throw new IllegalArgumentException("Invalid Order event orderId");}if(!order.equals(e.aggregateId())||!order.equals(e.correlationId()))throw new IllegalArgumentException("Order event aggregate/correlation does not match payload");if(e.messageType().equals("OrderConfirmed")&&(!e.payload().hasNonNull("amount")||!"INR".equals(e.payload().path("currency").asText())))throw new IllegalArgumentException("Confirmed event requires INR amount");if(!e.messageType().equals("OrderConfirmed")&&e.payload().path("reasonCode").asText().isBlank())throw new IllegalArgumentException("Rejected/cancelled event requires a reason code");return order;}
 private String subject(OrderEventEnvelope e){return switch(e.messageType()){case "OrderConfirmed"->"Order confirmed";case "OrderRejected"->"Order could not be accepted";default->"Order cancelled";};}
 private String body(OrderEventEnvelope e,UUID order){StringBuilder b=new StringBuilder("FulfillX order ").append(order).append(" is ").append(switch(e.messageType()){case "OrderConfirmed"->"confirmed";case "OrderRejected"->"rejected";default->"cancelled";}).append('.');if(e.messageType().equals("OrderConfirmed"))b.append(" Total: INR ").append(e.payload().path("amount").asText()).append('.');String reason=e.payload().path("reasonCode").asText("");if(!reason.isBlank())b.append(" Reason: ").append(reason).append('.');return b.toString();}
 private static Row map(ResultSet r)throws java.sql.SQLException{var until=r.getTimestamp("lease_until");return new Row(new NotificationMessage(r.getObject("notification_id",UUID.class),r.getObject("source_message_id",UUID.class),r.getObject("order_id",UUID.class),r.getObject("correlation_id",UUID.class),r.getString("event_type"),r.getString("recipient"),r.getString("subject"),r.getString("body")),r.getString("status"),until==null?null:until.toInstant());}
}
